-- Replace catalog data from the supplied 2026-10-28 exports.
-- Stage and validate before touching live rows. Existing internal IDs are retained
-- so orders, listing images, and asset references are not cascaded or orphaned.
-- Flyway executes this PostgreSQL migration in a single transaction.

CREATE TEMP TABLE catalog_import_asset_storage_provider ON COMMIT DROP AS SELECT public_id, provider_code, provider_name, bucket_name, endpoint_url, public_base_url, region_code, active, created_at, updated_at FROM asset_storage_provider WITH NO DATA;
ALTER TABLE catalog_import_asset_storage_provider ADD PRIMARY KEY (public_id);

CREATE TEMP TABLE catalog_import_asset ON COMMIT DROP AS SELECT public_id, provider_code, bucket_name, object_key, public_url, thumbnail_url, asset_type, owner_type, owner_id, content_type, file_size_bytes, width_pixels, height_pixels, alt_text, checksum_sha256, visibility, asset_status, created_by_user_public_id, created_at, updated_at FROM asset WITH NO DATA;
ALTER TABLE catalog_import_asset ADD PRIMARY KEY (public_id);

CREATE TEMP TABLE catalog_import_listing ON COMMIT DROP AS SELECT public_id, provider_account_public_id, created_by_user_public_id, title, description, category_code, vertical_code, product_type, delivery_type, fulfillment_scope, provider_country_code, currency_code, price_amount, listing_status, created_at, updated_at, seller_display_name, original_price_amount, image_key, condition_label, stock_quantity, featured, verified_seller, source_type, source_name, source_url, license_note, demo_seed, rollback_offer_expires_at FROM listing WITH NO DATA;
ALTER TABLE catalog_import_listing ADD PRIMARY KEY (public_id);

DO $$
BEGIN
    IF (SELECT COUNT(*) FROM catalog_import_asset_storage_provider) <> 2 THEN
        RAISE EXCEPTION 'Unexpected asset_storage_provider import row count';
    END IF;
    IF (SELECT COUNT(*) FROM catalog_import_asset) <> 67 THEN
        RAISE EXCEPTION 'Unexpected asset import row count';
    END IF;
    IF (SELECT COUNT(*) FROM catalog_import_listing) <> 83 THEN
        RAISE EXCEPTION 'Unexpected listing import row count';
    END IF;
END $$;

LOCK TABLE listing, asset, asset_storage_provider IN SHARE ROW EXCLUSIVE MODE;

-- Provider foreign keys use provider_code, not the exported public_id.
UPDATE asset_storage_provider existing
SET public_id = imported.public_id
FROM catalog_import_asset_storage_provider imported
WHERE existing.provider_code = imported.provider_code;

SELECT public_id, provider_code, provider_name, bucket_name, endpoint_url, public_base_url, region_code, active, created_at, updated_at FROM catalog_import_asset_storage_provider
ON CONFLICT (public_id) DO UPDATE SET
    provider_code = EXCLUDED.provider_code,
    provider_name = EXCLUDED.provider_name,
    bucket_name = EXCLUDED.bucket_name,
    endpoint_url = EXCLUDED.endpoint_url,
    public_base_url = EXCLUDED.public_base_url,
    region_code = EXCLUDED.region_code,
    active = EXCLUDED.active,
    created_at = EXCLUDED.created_at,
    updated_at = EXCLUDED.updated_at;

SELECT public_id, provider_code, bucket_name, object_key, public_url, thumbnail_url, asset_type, owner_type, owner_id, content_type, file_size_bytes, width_pixels, height_pixels, alt_text, checksum_sha256, visibility, asset_status, created_by_user_public_id, created_at, updated_at FROM catalog_import_asset
ON CONFLICT (public_id) DO UPDATE SET
    provider_code = EXCLUDED.provider_code,
    bucket_name = EXCLUDED.bucket_name,
    object_key = EXCLUDED.object_key,
    public_url = EXCLUDED.public_url,
    thumbnail_url = EXCLUDED.thumbnail_url,
    asset_type = EXCLUDED.asset_type,
    owner_type = EXCLUDED.owner_type,
    owner_id = EXCLUDED.owner_id,
    content_type = EXCLUDED.content_type,
    file_size_bytes = EXCLUDED.file_size_bytes,
    width_pixels = EXCLUDED.width_pixels,
    height_pixels = EXCLUDED.height_pixels,
    alt_text = EXCLUDED.alt_text,
    checksum_sha256 = EXCLUDED.checksum_sha256,
    visibility = EXCLUDED.visibility,
    asset_status = EXCLUDED.asset_status,
    created_by_user_public_id = EXCLUDED.created_by_user_public_id,
    created_at = EXCLUDED.created_at,
    updated_at = EXCLUDED.updated_at;

SELECT public_id, provider_account_public_id, created_by_user_public_id, title, description, category_code, vertical_code, product_type, delivery_type, fulfillment_scope, provider_country_code, currency_code, price_amount, listing_status, created_at, updated_at, seller_display_name, original_price_amount, image_key, condition_label, stock_quantity, featured, verified_seller, source_type, source_name, source_url, license_note, demo_seed, rollback_offer_expires_at FROM catalog_import_listing
ON CONFLICT (public_id) DO UPDATE SET
    provider_account_public_id = EXCLUDED.provider_account_public_id,
    created_by_user_public_id = EXCLUDED.created_by_user_public_id,
    title = EXCLUDED.title,
    description = EXCLUDED.description,
    category_code = EXCLUDED.category_code,
    vertical_code = EXCLUDED.vertical_code,
    product_type = EXCLUDED.product_type,
    delivery_type = EXCLUDED.delivery_type,
    fulfillment_scope = EXCLUDED.fulfillment_scope,
    provider_country_code = EXCLUDED.provider_country_code,
    currency_code = EXCLUDED.currency_code,
    price_amount = EXCLUDED.price_amount,
    listing_status = EXCLUDED.listing_status,
    created_at = EXCLUDED.created_at,
    updated_at = EXCLUDED.updated_at,
    seller_display_name = EXCLUDED.seller_display_name,
    original_price_amount = EXCLUDED.original_price_amount,
    image_key = EXCLUDED.image_key,
    condition_label = EXCLUDED.condition_label,
    stock_quantity = EXCLUDED.stock_quantity,
    featured = EXCLUDED.featured,
    verified_seller = EXCLUDED.verified_seller,
    source_type = EXCLUDED.source_type,
    source_name = EXCLUDED.source_name,
    source_url = EXCLUDED.source_url,
    license_note = EXCLUDED.license_note,
    demo_seed = EXCLUDED.demo_seed,
    rollback_offer_expires_at = EXCLUDED.rollback_offer_expires_at,
    featured_image_id = NULL,
    featured_image_url = NULL,
    featured_image_alt_text = NULL,
    featured_image_position = NULL;

DELETE FROM listing existing
WHERE NOT EXISTS (SELECT 1 FROM catalog_import_listing imported WHERE imported.public_id = existing.public_id);

DELETE FROM asset existing
WHERE NOT EXISTS (SELECT 1 FROM catalog_import_asset imported WHERE imported.public_id = existing.public_id);

DELETE FROM asset_storage_provider existing
WHERE NOT EXISTS (SELECT 1 FROM catalog_import_asset_storage_provider imported WHERE imported.public_id = existing.public_id);

DO $$
BEGIN
    IF EXISTS (SELECT public_id, provider_code, provider_name, bucket_name, endpoint_url, public_base_url, region_code, active, created_at, updated_at FROM asset_storage_provider EXCEPT SELECT public_id, provider_code, provider_name, bucket_name, endpoint_url, public_base_url, region_code, active, created_at, updated_at FROM catalog_import_asset_storage_provider)
        OR EXISTS (SELECT public_id, provider_code, provider_name, bucket_name, endpoint_url, public_base_url, region_code, active, created_at, updated_at FROM catalog_import_asset_storage_provider EXCEPT SELECT public_id, provider_code, provider_name, bucket_name, endpoint_url, public_base_url, region_code, active, created_at, updated_at FROM asset_storage_provider) THEN
        RAISE EXCEPTION 'asset_storage_provider does not match the supplied export';
    END IF;
    IF EXISTS (SELECT public_id, provider_code, bucket_name, object_key, public_url, thumbnail_url, asset_type, owner_type, owner_id, content_type, file_size_bytes, width_pixels, height_pixels, alt_text, checksum_sha256, visibility, asset_status, created_by_user_public_id, created_at, updated_at FROM asset EXCEPT SELECT public_id, provider_code, bucket_name, object_key, public_url, thumbnail_url, asset_type, owner_type, owner_id, content_type, file_size_bytes, width_pixels, height_pixels, alt_text, checksum_sha256, visibility, asset_status, created_by_user_public_id, created_at, updated_at FROM catalog_import_asset)
        OR EXISTS (SELECT public_id, provider_code, bucket_name, object_key, public_url, thumbnail_url, asset_type, owner_type, owner_id, content_type, file_size_bytes, width_pixels, height_pixels, alt_text, checksum_sha256, visibility, asset_status, created_by_user_public_id, created_at, updated_at FROM catalog_import_asset EXCEPT SELECT public_id, provider_code, bucket_name, object_key, public_url, thumbnail_url, asset_type, owner_type, owner_id, content_type, file_size_bytes, width_pixels, height_pixels, alt_text, checksum_sha256, visibility, asset_status, created_by_user_public_id, created_at, updated_at FROM asset) THEN
        RAISE EXCEPTION 'asset does not match the supplied export';
    END IF;
    IF EXISTS (SELECT public_id, provider_account_public_id, created_by_user_public_id, title, description, category_code, vertical_code, product_type, delivery_type, fulfillment_scope, provider_country_code, currency_code, price_amount, listing_status, created_at, updated_at, seller_display_name, original_price_amount, image_key, condition_label, stock_quantity, featured, verified_seller, source_type, source_name, source_url, license_note, demo_seed, rollback_offer_expires_at FROM listing EXCEPT SELECT public_id, provider_account_public_id, created_by_user_public_id, title, description, category_code, vertical_code, product_type, delivery_type, fulfillment_scope, provider_country_code, currency_code, price_amount, listing_status, created_at, updated_at, seller_display_name, original_price_amount, image_key, condition_label, stock_quantity, featured, verified_seller, source_type, source_name, source_url, license_note, demo_seed, rollback_offer_expires_at FROM catalog_import_listing)
        OR EXISTS (SELECT public_id, provider_account_public_id, created_by_user_public_id, title, description, category_code, vertical_code, product_type, delivery_type, fulfillment_scope, provider_country_code, currency_code, price_amount, listing_status, created_at, updated_at, seller_display_name, original_price_amount, image_key, condition_label, stock_quantity, featured, verified_seller, source_type, source_name, source_url, license_note, demo_seed, rollback_offer_expires_at FROM catalog_import_listing EXCEPT SELECT public_id, provider_account_public_id, created_by_user_public_id, title, description, category_code, vertical_code, product_type, delivery_type, fulfillment_scope, provider_country_code, currency_code, price_amount, listing_status, created_at, updated_at, seller_display_name, original_price_amount, image_key, condition_label, stock_quantity, featured, verified_seller, source_type, source_name, source_url, license_note, demo_seed, rollback_offer_expires_at FROM listing) THEN
        RAISE EXCEPTION 'listing does not match the supplied export';
    END IF;
END $$;
